frameworks.vanilla:
// Mount and bind Area Chart Default
const container = document.getElementById("area-default");
if (container) {
  container.querySelectorAll("[data-series]").forEach((el) => {
    el.addEventListener("mouseenter", () => {
      container.querySelector("[data-slot='tooltip']")?.setAttribute("data-state", "visible");
    });
    el.addEventListener("mouseleave", () => {
      container.querySelector("[data-slot='tooltip']")?.setAttribute("data-state", "hidden");
    });
  });
}

frameworks.astro:
---
// AreaDefaultChart.astro
interface Props {
  title?: string;
  description?: string;
  class?: string;
}
const { title = "Area Chart Default", description = "Smooth curved single series area chart with vertical fill.", class: className = "" } = Astro.props;
---
<div id="area-default" class:list={["w-full", className]}>
  <div class="card p-6 flex flex-col gap-4 w-full">
  <div class="border-b border-border pb-3">
    <h3 class="text-base font-semibold">Area Chart Default</h3>
    <p class="text-sm text-muted-foreground">Smooth curved single series area chart with vertical fill.</p>
  </div>
  <svg class="h-48 w-full" viewBox="0 0 400 160" role="img" aria-label="Area Chart">
        <defs>
          <linearGradient id="grad-area-default" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stop-color="var(--chart-1)" stop-opacity="0.35"/>
            <stop offset="100%" stop-color="var(--chart-1)" stop-opacity="0.0"/>
          </linearGradient>
        </defs>
        <path d="M0,130 Q100,50 200,90 T400,30 L400,160 L0,160 Z" fill="url(#grad-area-default)"/>
        <path d="M0,130 Q100,50 200,90 T400,30" fill="none" stroke="var(--chart-1)" stroke-width="2.5"/>
      </svg>
  <div class="flex items-center justify-between border-t border-border pt-3 text-xs text-muted-foreground">
    <span>Series Total</span>
    <strong class="tabular-nums font-semibold text-foreground">$14,250.00</strong>
  </div>
</div>
</div>
<script>
  const root = document.getElementById("area-default");
  root?.querySelectorAll("[data-series]").forEach(el => {
    el.addEventListener("mouseenter", () => root.querySelector("[data-slot='tooltip']")?.setAttribute("data-state", "visible"));
    el.addEventListener("mouseleave", () => root.querySelector("[data-slot='tooltip']")?.setAttribute("data-state", "hidden"));
  });
</script>

